int lov_pool_del ( struct obd_device * obd , char * poolname ) { struct lov_obd * lov ; struct pool_desc * pool ; lov = & obd -> u . lov ; pool = cfs_hash_del_key ( lov -> lov_pools_hash_body , poolname ) ; if ( ! pool ) { return - ENOENT ; } if ( ! IS_ERR_OR_NULL ( pool -> pool_debugfs_entry ) ) { CDEBUG ( D_INFO , "proc entry %p\n" , pool -> pool_debugfs_entry ) ; ldebugfs_remove ( & pool -> pool_debugfs_entry ) ; lov_pool_putref ( pool , NULL ) ; } spin_lock ( & obd -> obd_dev_lock ) ; list_del_init ( & pool -> pool_list ) ; lov -> lov_pool_count -- ; spin_unlock ( & obd -> obd_dev_lock ) ; lov_pool_putref ( pool ) ; return 0 ; } 